//! Shiftella — entry point. The game itself lives in the library (`src/lib.rs`):
//! [`shiftella_game::app::run`] boots, shows the menu and runs the state machine.

use macroquad::miniquad::conf::Icon;
use macroquad::prelude::*;

/// Window / Dock icon (raw RGBA, generated by `tools/make_icon.py --rgba assets/icon`).
/// Without it macroquad shows its own default icon while the game runs.
fn icon() -> Icon {
    Icon {
        small: *include_bytes!("../assets/icon/icon_16.rgba"),
        medium: *include_bytes!("../assets/icon/icon_32.rgba"),
        big: *include_bytes!("../assets/icon/icon_64.rgba"),
    }
}

fn window_conf() -> Conf {
    Conf {
        window_title: "Shiftella".to_owned(),
        window_width: 1280,
        window_height: 720,
        high_dpi: true,  // crisp on Retina
        sample_count: 4, // MSAA
        icon: Some(icon()),
        ..Default::default()
    }
}

#[macroquad::main(window_conf)]
async fn main() {
    shiftella_game::app::run().await;
}
